package dev.mcmod.hdfv.airport;

import java.util.List;

/**
 * An airport's size (0.21): LARGE is 0.20's airport, MEDIUM and SMALL are scaled down from it (the user: "the airport
 * now is the large one, medium and small are smaller"). LARGE is the first (ordinal 0): 0.20's saved plans have no
 * tier and read as it. Every number of LARGE is 0.20's, so airports half generated by 0.20 are finished the same.
 * <p>
 * The spec, in metres (along the runway / across it, from the runway's centre line toward the plan's side):
 * <ul>
 *   <li>runway width, the lengths tried (longest first), the cut and fill the planner allows;</li>
 *   <li>the grass strip beside the runway and past its ends;</li>
 *   <li>the parallel taxiway (0: none) and how far in from the runway's ends it starts, its width; the links to the
 *   runway (3: both ends and the middle, 2: both ends, 1: one stub in the middle to the apron), how far in from the
 *   ends, their width; the holding position's distance from the centre line;</li>
 *   <li>the apron (beyond the taxiway, or {@code apronGap} beyond the runway's edge without one), the hangar and the
 *   tower beyond the apron (their near ends along, from the runway's middle; no tower when towerAt is NONE);</li>
 *   <li>the tower's shaft courses, the approach-light strips, centre line lights, PAPI units (0 none), the batteries
 *   in the tower's base, windsocks, holding signs (one a link), apron floodlights, whether it has lights at all.</li>
 * </ul>
 */
public enum AirportTier {
    LARGE(new Spec(23, List.of(900, 800, 700, 600), 24, 18, 50, 30,
            75, 30, 15, 3, 40, 18, 50, 120, 80, 0, 30, 24, 10, -55, 30, 8, 16,
            150, true, 4, 300, 8, 2, true, 2, true)),
    MEDIUM(new Spec(18, List.of(550, 500, 450, 400), 16, 12, 35, 30,
            45, 20, 12, 2, 25, 15, 30, 70, 45, 0, 20, 16, 7, -38, 15, 6, 8,
            0, false, 2, 200, 4, 1, true, 1, true)),
    SMALL(new Spec(15, List.of(400, 350, 300, 250), 10, 8, 20, 20,
            0, 0, 0, 1, 0, 12, 15, 40, 25, 20, 12, 10, 5, -18, Spec.NONE, 0, 0,
            0, false, 0, 0, 0, 1, false, 0, false));

    public final Spec spec;

    AirportTier(Spec spec) { this.spec = spec; }

    public record Spec(int widthM, List<Integer> lengths, int cutM, int fillM, int stripSide, int stripEnd,
                       int taxiOffset, int taxiInset, int taxiWidth, int links, int linkInset, int linkWidth, int holdM,
                       int apronLong, int apronDeep, int apronGap, int hangarLong, int hangarDeep, int hangarHigh, int hangarAt,
                       int towerAt, int minCourses, int maxCourses,
                       int approach, boolean centreLights, int papiUnits, int papiMaxM, int batteries, int windsocks,
                       boolean holdSigns, int floodlights, boolean lit) {
        /** No tower. */
        public static final int NONE = Integer.MIN_VALUE;

        public boolean tower() { return towerAt != NONE; }

        public boolean taxiway() { return taxiOffset > 0; }
    }

    /**
     * A tower's courses from the planner's draw (8 to 16, 0.20's): kept for LARGE, folded into this tier's range for the
     * others (no draw added: the candidates after it stay as they were).
     */
    public int courses(int drawn) {
        if (!spec.tower()) { return 0; }
        if (this == LARGE) { return drawn; }
        return spec.minCourses() + Math.floorMod(drawn - 8, spec.maxCourses() - spec.minCourses() + 1);
    }
}
